<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimeImportDiscountRead,RuntimeHttpException};
use PHPUnit\Framework\TestCase;
final class SupplierSelectionHelperTest extends TestCase {
 private function resolve(string $action,array $payload):array{$definition=['entityCode'=>'descontos_importacao_fornecedor_progress','primaryKey'=>'record_key','apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros'],'apiSource'=>['responseContract'=>'sursum-programs'],'fields'=>['fornecedor_id'=>['dataType'=>'integer']]];return RuntimeImportDiscountRead::resolveContext($definition,['url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/ciw-cadastros','method'=>'POST','requestContextFields'=>['fornecedor_id'],'bodyTemplate'=>['operation'=>$action,'resource'=>'import_descontos_fornecedor']],$payload);}
 private function filter(int $id):array{return['field'=>'fornecedor_id','operator'=>'eq','value'=>$id];}
 public function testReadFixedSignedEqFilterDerivesSupplierAndOptionalContextMustAgree():void{foreach([0,-9,-2147483648,2147483647,7]as$id){$payload=['filters'=>[$this->filter($id)]];self::assertSame(['fornecedor_id'=>$id],$this->resolve('read',$payload));self::assertSame(['fornecedor_id'=>$id],$this->resolve('read',$payload+['context'=>['fornecedor_id'=>$id]]));self::assertSame(['fornecedor_id'=>$id],$this->resolve('read',['filter'=>['logic'=>'and','filters'=>[$this->filter($id),$this->filter($id)]]]));}}
 public function testNoSelectionOrInvalidContextOrOrConflictFailsClosed():void{foreach([[],['filters'=>[]],['filters'=>[['field'=>'vl_saldo','operator'=>'eq','value'=>0]]],['filters'=>[$this->filter(0)],'context'=>[]],['filters'=>[$this->filter(0)],'context'=>null],['filters'=>[$this->filter(0)],'context'=>['fornecedor_id'=>-9]],['filters'=>[$this->filter(0)],'context'=>['fornecedor_id'=>0,'other'=>1]],['filters'=>[$this->filter(0),$this->filter(-9)]],['filter'=>['logic'=>'or','filters'=>[$this->filter(0),$this->filter(0)]]],['filters'=>[['field'=>'fornecedor_id','operator'=>'neq','value'=>0]]],['filters'=>[['field'=>'fornecedor_id','operator'=>'eq','value'=>'0']]]]as$payload){try{$this->resolve('read',$payload);self::fail('Ambiguous selection accepted');}catch(RuntimeHttpException $error){self::assertSame(422,$error->getStatusCode());}}}
 public function testGetStillRequiresExactExplicitContextEvenWithFilter():void{foreach([0,-9,-2147483648]as$id){self::assertSame(['fornecedor_id'=>$id],$this->resolve('get',['context'=>['fornecedor_id'=>$id]]));try{$this->resolve('get',['filters'=>[$this->filter($id)]]);self::fail('GET cannot derive scope from filters');}catch(RuntimeHttpException $error){self::assertSame(422,$error->getStatusCode());}}}
}
